-- Ange, offert à tous les abonnés. À coller dans Supabase > SQL Editor après schema.sql.
-- Ses fichiers restent sur le site (chemins qui commencent par /) : rien à déposer dans le stockage.
-- Pour les histoires suivantes, les chemins seront ceux du stockage privé, sans / au début,
-- par exemple « la-suivante/4-6/histoire.pdf ».
insert into public.histoires (slug, titre, theme, date_sortie, offerte, contenu) values (
  'ange-le-loup',
  'Ange, le loup qui chantait avec le vent',
  'Appartenance, différence, courage d''être soi',
  '2026-12-12 09:00:00+01',
  true,
  '{"4-6":{"texte":{"titre":"Ange, le loup qui chantait avec le vent","age":"Adaptation 4-6 ans","paragraphes":["Tu connais le grand secret de la forêt de Daillon ? Approche, installe-toi bien. Je vais te raconter l''histoire du loup Ange. Un loup pas comme les autres.","Dans la forêt de Daillon, les arbres sont si grands qu''ils font des guiliguilis aux nuages. Là vit le loup Ange. Chaque matin, il sort de sa tanière, sa maison de loup. Mais lui, il marche sur la pointe des pattes. Chhhht, chhhht, chhhht. Sans faire de bruit, comme une ombre.","Pourquoi ? Parce qu''Ange adore écouter la forêt. Le frouuuu-frouuuu du vent dans les feuilles. Le glouglou-glouglou du Riou Maffren, le petit ruisseau. C''est sa musique préférée.","Mais il y a un problème. Un gros problème.","« Si on me voit, tout le monde va se sauver… » soupire Ange.","Et c''est vrai. Quand Ange éternue, ATCHOUM, les lapins partent en courant. Quand il marche trop fort, BOUM, BOUM, BOUM, les oiseaux s''envolent. Et quand il bâille, avec ses grandes dents… tout le monde a peur !","Alors Ange a décidé de rester caché. Ça lui fait de la peine. Il rêve d''avoir des amis, de rire avec eux, de courir dans les fougères. Mais il préfère se cacher, pour que personne n''ait peur dans sa forêt.","•••","Un matin d''automne, tout change.","Les feuilles tombent, jaunes, orange et rouges. Ce matin-là, le Riou Maffren coule très fort. Splish, splash, splosh ! Il fait tellement de bruit qu''Ange se dit : « Tiens ! Pour une fois, je peux me promener sans faire attention. »","Et là, une tache rousse arrive devant lui en sautillant.","« AAAAAANGE ! » crie une voix joyeuse.","Ange sursaute si fort qu''il manque de tomber. C''est Posey, le renard roux, avec son grand sourire.","« Ce soir, c''est la grande fête de Daillon ! » dit Posey, tout content.","La fête de Daillon ! C''est la plus grande fête de l''année. Il y a le tournoi de péglandque : on lance des glands près d''un champignon doré. Il y a un grand repas préparé par Gaston le sanglier, le cuisinier. Et surtout, il y a la musique de DJ Snake, le serpent musicien ! Snake, ça veut dire « serpent » en anglais.","Posey regarde Ange.","« Tu as raté la fête l''an dernier. Et celle d''avant ! Cette année, tu viens avec nous. »","Ange baisse la tête.","« Oh non… Je ferais trop peur à tout le monde, Posey. Je ne suis pas à ma place là-bas. »","Le renard fronce les sourcils.","« Mais si ! C''est la fête de TOUS les animaux de Daillon. Toi aussi ! Tu habites cette forêt, comme nous tous. »","Ange sent un petit espoir dans son cœur. Mais non. Non, non, non.","« Merci, Posey. Mais j''ai encore beaucoup de choses à préparer avant l''hiver… »","Ce n''est pas vrai. Et Posey le sait bien. Le renard soupire.","« Comme tu veux, mon ami. Mais la porte est toujours ouverte. »","Et il s''en va entre les fougères.","•••","L''après-midi passe vite. Dans la clairière, on entend des rires. Clic-clac ! Les glands volent pendant le tournoi de péglandque.","Le soir arrive. La lune se lève. Les champignons s''allument un par un, gling, gling, gling, comme des petites lampes. DJ Snake met sa musique, et toute la forêt se met à danser. Boum-tchak, boum-tchak !","Dans sa tanière, Ange n''arrive pas à dormir. Il entend la musique. Il entend les rires. Il se tourne, il se retourne.","« Après tout, dit-il tout bas, je pourrais juste regarder de loin ? »","Ange va vers la clairière. Il se cache derrière un gros chêne. Assez loin pour qu''on ne le voie pas. Assez près pour tout entendre.","Et là… oh là là ! Les lapins sautent au rythme de la musique. Les fouines tournent avec les hérissons. Même les chouettes battent des ailes en mesure. Tout le monde rit.","Ange s''allonge dans les feuilles, avec un sourire. Même de loin, il fait partie de la fête.","•••","Mais tu sais ce qu''on dit : quand tout va trop bien…","Ange le sent avant tout le monde. Un petit frisson dans l''air. Il dresse les oreilles.","Le vent. Le vent se lève. Un vent de tempête, un vent en colère qui fait : Houuuuuuuuuuu !","En quelques secondes, la fête se transforme en panique. Les feuilles s''envolent. Les champignons-lampes tremblent. Les animaux tournent dans tous les sens, poussés par le vent.","« AU SECOURS ! » crie un animal. « Vite, il faut se cacher ! » crie Posey. Mais où ? On ne voit plus rien !","Ange se lève d''un bond. Ses yeux de loup voient bien dans le noir. Et là, il voit un petit creux, en bas, près du Riou Maffren. Un abri entre les rochers. Parfait.","Mais comment montrer le chemin à tout le monde ?","Le cœur d''Ange bat très fort. Boum-boum. Boum-boum. BOUM-BOUM.","Alors, sans réfléchir, Ange prend une grande, grande inspiration. Il lève son museau vers le ciel. Et il hurle.","« AOUUUUUUUUUUUUUUUUUUUU ! »","Le hurlement traverse la nuit. Fort et clair, comme une grande lumière dans la tempête. Il dit : « Par ici ! Je suis là ! Suivez-moi ! »","Posey reconnaît tout de suite cette voix.","« C''est Ange ! crie-t-il. Il nous guide ! Vite, suivons sa voix ! »","Et là, quelque chose d''extraordinaire arrive. Personne n''a peur. Personne ne se sauve. Tous les animaux vont vers le hurlement. Les lapins, les oiseaux, les blaireaux, les hérissons, les écureuils, tous courent vers sa voix.","« AOUUUUUUUUUUUUUUUUUUUU ! PAR ICI ! ENCORE UN PETIT EFFORT ! »","Quelques minutes plus tard, tous les animaux de Daillon sont à l''abri. Serrés les uns contre les autres. Tout mouillés, mais sains et saufs. Le vent se calme. La tempête s''en va. Le silence revient. Un silence doux et paisible.","Posey s''approche d''Ange. Ses yeux brillent.","« Ton hurlement… dit-il tout doucement. C''était magnifique. Tu nous as guidés jusqu''ici ! »","« Merci, Ange ! » « Tu es un héros ! » disent tous les animaux.","Ange ne sait plus où se mettre. Ses joues deviennent toutes rouges sous sa fourrure. Son cœur bat à toute vitesse, mais cette fois, c''est de bonheur.","Le blaireau s''avance, avec un grand sourire.","« Bon ! dit-il de sa grosse voix. Maintenant qu''on est tous sauvés, on retourne faire la fête ENSEMBLE ! »","•••","Tous les animaux crient « hourra ! ». DJ Snake remet sa musique. Cette fois, Ange danse au milieu de tout le monde, le cœur léger.","Depuis ce soir-là, quand le vent souffle dans la forêt de Daillon, on entend le loup Ange chanter avec lui. Un chant fort et libre. Et toute la forêt écoute, sans peur.","Parce que tu sais quoi ? Ce n''est pas la fourrure ni les grandes dents qui comptent. Ce qui compte, c''est le courage du cœur. Tout le monde a sa place dans la forêt, même celle ou celui qui se sent à part. Et parfois, il suffit d''un hurlement dans la tempête pour le comprendre."],"morale":["Tu as le droit d''être toi."]},"histoire":"/assets/pdf/ange/ange-4-6-histoire.pdf","papote":"/assets/pdf/ange/ange-4-6-fiche-papote.pdf","activites":[{"titre":"Le péglandque, le vrai","type":"jeu de lancer","pdf":"/assets/pdf/ange/ange-4-6-01-peglandque.pdf"},{"titre":"La voix dans la tempête","type":"jeu signature","pdf":"/assets/pdf/ange/ange-4-6-02-jeu-signature.pdf"},{"titre":"Le concert de la forêt","type":"jeu musical","pdf":"/assets/pdf/ange/ange-4-6-03-concert-de-la-foret.pdf"},{"titre":"Le théâtre d’ombres du loup","type":"théâtre d’ombres","pdf":"/assets/pdf/ange/ange-4-6-04-theatre-ombres.pdf"},{"titre":"Le chemin des AOUUU","type":"labyrinthe","pdf":"/assets/pdf/ange/ange-4-6-05-labyrinthe.pdf"},{"titre":"Ange caché, Ange qui chante","type":"coloriage","pdf":"/assets/pdf/ange/ange-4-6-06-coloriage.pdf"},{"titre":"La fête de Daillon","type":"cherche et trouve","pdf":"/assets/pdf/ange/ange-4-6-07-cherche-et-trouve.pdf"},{"titre":"Mon cri à moi","type":"jeu d’écoute","pdf":"/assets/pdf/ange/ange-4-6-08-mon-cri-a-moi.pdf"},{"titre":"Ma carte force","type":"ma force cachée","pdf":"/assets/pdf/ange/ange-4-6-09-ma-force-cachee.pdf"},{"titre":"Le permis de hurler","type":"diplôme","pdf":"/assets/pdf/ange/ange-4-6-10-diplome.pdf"},{"titre":"Le cri de la forêt","type":"rituel","pdf":"/assets/pdf/ange/ange-4-6-11-cri-de-la-foret.pdf"},{"titre":"Le tri des émotions","type":"tri des émotions","pdf":"/assets/pdf/ange/ange-4-6-12-tri-des-emotions.pdf"}],"bonus":[{"titre":"Les mots de la forêt","type":"mots mêlés","pdf":"/assets/pdf/ange/ange-4-6-bonus-1-mots-meles.pdf"},{"titre":"Cherche les 7 différences","type":"jeu des différences","pdf":"/assets/pdf/ange/ange-4-6-bonus-2-jeu-des-differences.pdf"},{"titre":"L’histoire dans l’ordre","type":"vignettes","pdf":"/assets/pdf/ange/ange-4-6-bonus-3-vignettes.pdf"},{"titre":"L’interview d’Ange","type":"interview","pdf":"/assets/pdf/ange/ange-4-6-bonus-4-interview.pdf"}]},"7-9":{"texte":{"titre":"Ange, le loup qui chantait avec le vent","age":"Adaptation 7-9 ans","paragraphes":["Tu connais le secret le mieux gardé de la forêt de Daillon ? Approche, installe-toi bien, je vais te raconter l''histoire du loup Ange. Un loup pas comme les autres…","Au cœur de la forêt de Daillon, là où les arbres sont si hauts qu''ils chatouillent les nuages, vit Ange. Chaque matin, quand la brume se lève entre les branches, il sort de sa tanière tapissée de mousse. Mais lui, il marche sur la pointe des pattes. Chhht, chhht, chhht. Silencieux comme une ombre.","Pourquoi tant de précautions ? Parce qu''Ange adore par-dessus tout écouter la musique de la forêt. Le cric-crac des branches sous les pattes des lapins. Le frou-frou du vent dans les feuilles. Le glouglou joyeux du Riou Maffren, le petit ruisseau qui file entre les rochers. C''est sa musique préférée, son trésor de chaque jour.","Mais il y a un problème. Un gros problème.","« Si on me voit, tout le monde va fuir… » soupire Ange en regardant son reflet dans l''eau claire du ruisseau.","Et c''est vrai. Ange l''a vérifié plus d''une fois. Quand il éternue, ATCHOUM, les lapins détalent comme des fusées. Quand il marche un peu trop fort, BOUM, BOUM, BOUM, les oiseaux s''envolent en piaillant. Et s''il a le malheur de bâiller en montrant ses grandes dents blanches… je te laisse imaginer la panique !","Alors Ange a pris une décision qui lui serre le cœur : il restera discret, comme un fantôme gris dans les bois. Ce n''est pas la vie dont il rêve. Il rêve d''amis, de rires partagés, de courses folles dans les fougères. Mais il préfère se cacher, pour que tout le monde se sente en sécurité dans sa forêt.","•••","Un matin d''automne, quelque chose change.","Les feuilles se couvrent de couleurs : jaune citron, orange mandarine, rouge cerise. Ce matin-là, le Riou Maffren coule plus fort que jamais, gonflé par la pluie de la nuit. Splish, splash, splosh ! Il fait tant de bruit qu''Ange se dit : « Tiens ! Pour une fois, je peux me promener sans faire attention. »","Il s''aventure un peu plus loin que d''habitude, le nez au vent. C''est alors qu''une tache rousse surgit devant lui en sautillant.","« AAAAAANGE ! » crie une voix joyeuse.","Le loup sursaute si fort qu''il manque de tomber à la renverse. Devant lui se tient Posey, le renard roux, avec son sourire malicieux et sa queue en panache.","« Ce soir, c''est la grande fête de Daillon ! » annonce Posey, les yeux brillants.","La fête de Daillon ! Rien que ce nom fait battre le cœur de tous les habitants de la forêt. C''est la fête de l''année, celle qu''on attend pendant des mois. Au programme : le tournoi de péglandque, ce jeu où l''on lance des glands le plus près possible d''un champignon doré. Un grand repas préparé par Gaston le sanglier, le chef cuisinier au flair célèbre, aidé des écureuils. Et surtout, la musique de DJ Snake, le serpent musicien ! Snake, ça veut dire « serpent » en anglais. Personne n''a jamais compris pourquoi il tient tant à son nom en anglais, mais bon… c''est son style.","Posey regarde Ange avec insistance.","« Tu as raté la fête l''an dernier. Et celle d''avant ! Cette année, je ne te laisse pas broyer du noir tout seul, mon vieux. »","Ange baisse la tête. Son ventre se noue.","« Oh non… Je ferais bien trop peur à tout le monde, Posey. Ils attendent cette fête depuis des mois, je ne veux pas tout gâcher avec ma tête de loup. Je ne suis pas à ma place là-bas. »","Le renard fronce les sourcils.","« Des bêtises ! C''est la fête de TOUS les habitants de Daillon. Toi aussi ! Tu habites cette forêt autant que moi, autant que les lapins ou les merles. Et puis, ajoute-t-il avec un clin d''œil, le blaireau tiendra le bar à jus de mûre. Tu sais comme il est généreux… »","Ange sent un tout petit espoir remuer dans son cœur. Mais non. Non, non, non.","« Merci, Posey, vraiment. Mais j''ai encore plein de choses à préparer avant l''hiver… »","Ce n''est pas vrai. Ange a tout préparé depuis des semaines, et Posey le sait très bien. Le renard soupire doucement.","« Comme tu veux, mon ami. Mais la porte est toujours ouverte pour les habitants de Daillon. »","Et il disparaît entre les fougères, sa queue rousse balayant les feuilles mortes.","•••","L''après-midi file à toute vitesse. Dans la clairière, les rires fusent. Clic-clac ! Les glands volent pendant le tournoi de péglandque. Gaston fait mijoter sa soupe aux champignons dans une énorme marmite, et les écureuils courent partout avec des plateaux de gâteaux aux noisettes.","Le soir tombe. La lune se lève. Les champignons de la forêt s''allument un à un, gling, gling, gling, comme des lampions magiques : bleus, verts, violets. DJ Snake lance sa musique, et toute la forêt se met à danser. Boum-tchak, boum-tchak !","Dans sa tanière, Ange n''arrive pas à fermer l''œil. Le sol tremble sous les pattes qui dansent. Les rires arrivent jusqu''à lui. Il se tourne, se retourne, soupire.","« Après tout, murmure-t-il, je pourrais peut-être juste regarder de loin ? »","Voir sans être vu : c''est ça, la solution ! Ange se faufile hors de sa tanière et s''installe derrière un gros chêne, assez loin pour ne pas être remarqué, assez près pour tout entendre.","Et là… oh là là ! Les lapins sautillent au rythme de la musique. Les fouines tournoient avec les hérissons. Sous une grande tente, d''autres hérissons grignotent des gâteaux, et une petite souris grimpe aux guirlandes pour mieux voir. Même les chouettes battent des ailes en mesure, perchées sur les branches. Tout le monde rit.","Ange s''allonge dans les feuilles sèches, un sourire sur le museau. Pour la première fois depuis longtemps, il se sent presque heureux. Même de loin, il fait partie de quelque chose de grand et de beau.","•••","Mais tu sais ce qu''on dit : quand tout va trop bien…","Ange le sent avant tout le monde. Un frisson glacé court sur sa fourrure. Il dresse les oreilles. Le vent se lève. Un vent de tempête, un vent en colère qui fait : Houuuuuuuuu !","En quelques secondes, la fête se transforme en chaos. Les guirlandes de feuilles s''envolent. Les champignons lumineux vacillent. Les animaux tournoient malgré eux, emportés par des tourbillons de feuilles et de poussière.","« AU SECOURS ! » hurle quelqu''un. « Vite, il faut s''abriter ! » crie Posey de sa voix la plus forte.","Mais où ? On n''y voit plus rien ! Le vent souffle de partout à la fois. C''est la panique.","Ange se redresse d''un bond. Ses yeux de loup, habitués à percer le noir, fouillent la forêt. Et là, il voit un petit creux, en contrebas, près du Riou Maffren : un abri naturel entre les rochers et les racines des vieux arbres. Parfait.","Mais comment montrer le chemin à tout le monde, dans ce chaos ?","Le cœur d''Ange bat si fort qu''il l''entend dans ses oreilles. Boum-boum. Boum-boum. BOUM-BOUM.","Alors, sans plus réfléchir, Ange prend la plus grande inspiration de toute sa vie. Il lève son museau vers le ciel noir. Et il hurle.","« AOUUUUUUUUUUUUUUUUUUU ! »","Le hurlement clair déchire la nuit, puissant comme un phare dans la tempête. Il rebondit d''arbre en arbre, de rocher en rocher, et il dit : « Par ici ! Je suis là ! Suivez-moi ! »","Posey reconnaît aussitôt cette voix. Les larmes lui montent aux yeux.","« C''est Ange ! crie-t-il. Il nous guide ! Vite, tout le monde, suivons sa voix ! »","Et quelque chose d''extraordinaire arrive. Personne ne prend peur. Personne ne s''enfuit. Tous les animaux se tournent vers le hurlement, comme des fleurs vers le soleil. Les lapins bondissent, les oiseaux volent malgré le vent, les blaireaux, les hérissons et les écureuils courent vers la voix d''Ange.","« AOUUUUUUUUUUUUUUUUUUU ! PAR ICI ! ENCORE UN PETIT EFFORT ! »","Quelques minutes plus tard, tous les habitants de Daillon sont à l''abri, serrés les uns contre les autres. Trempés, décoiffés, mais sains et saufs. Le vent finit par se calmer. La tempête s''éloigne en grondant. Le silence revient, un silence doux, plein de respirations soulagées.","Posey s''approche d''Ange, les yeux brillants.","« Ton hurlement… dit-il d''une voix tremblante. C''était magnifique. Sans toi, on ne sait pas ce qu''on serait devenus. »","« Merci, Ange ! » « Merci de nous avoir sauvés ! » « Ta voix nous a rassurés ! » disent les animaux, un par un.","Ange ne sait plus où regarder. Ses joues rougissent sous sa fourrure grise. Son cœur bat à toute vitesse, mais cette fois, c''est de bonheur.","Le blaireau s''avance, un grand sourire sur son museau rayé.","« Bon ! lance-t-il de sa grosse voix. Maintenant qu''on est tous sauvés, on retourne faire la fête, ENSEMBLE. Et les jus de mûre sont pour moi ! »","•••","Un immense « hourra ! » s''élève de la petite troupe trempée. DJ Snake retrouve ses platines, intactes par miracle, et relance la musique. Cette fois, Ange ne reste pas à l''écart. Il danse au milieu de tous, le cœur léger comme une plume.","Depuis ce soir-là, quand le vent souffle à travers la forêt de Daillon, on entend le loup Ange chanter avec lui. Un chant puissant et libre. Et toute la forêt l''écoute, sans peur.","Parce que tu sais quoi ? Ce n''est pas la fourrure ni les grandes dents qui disent qui l''on est. Ce qui compte, c''est le courage du cœur et la générosité. Chacune et chacun a sa place dans le monde, même celle ou celui qui se croit différent. Et parfois, il suffit d''un hurlement dans la tempête pour le découvrir.","Tu n''as pas besoin d''être comme les autres pour avoir ta place. Tu as juste besoin d''être toi."],"morale":[]},"histoire":"/assets/pdf/ange/ange-7-9-histoire.pdf","papote":"/assets/pdf/ange/ange-7-9-fiche-papote.pdf","activites":[{"titre":"Le labyrinthe de la tempête","type":"labyrinthe","pdf":"/assets/pdf/ange/ange-7-9-01-labyrinthe.pdf"},{"titre":"Les bruits de Daillon","type":"mots mêlés","pdf":"/assets/pdf/ange/ange-7-9-02-mots-meles.pdf"},{"titre":"La nuit de la tempête","type":"coloriage","pdf":"/assets/pdf/ange/ange-7-9-03-coloriage.pdf"},{"titre":"La fête de Daillon","type":"cherche et trouve","pdf":"/assets/pdf/ange/ange-7-9-04-cherche-et-trouve.pdf"},{"titre":"Le péglandque, le vrai","type":"jeu de lancer","pdf":"/assets/pdf/ange/ange-7-9-05-peglandque.pdf"},{"titre":"La voix dans la tempête","type":"jeu signature","pdf":"/assets/pdf/ange/ange-7-9-06-jeu-signature.pdf"},{"titre":"Le concert de la forêt","type":"jeu musical","pdf":"/assets/pdf/ange/ange-7-9-07-concert-de-la-foret.pdf"},{"titre":"Ma carte force","type":"ma force cachée","pdf":"/assets/pdf/ange/ange-7-9-08-ma-force-cachee.pdf"},{"titre":"Le théâtre d’ombres du loup","type":"théâtre d’ombres","pdf":"/assets/pdf/ange/ange-7-9-09-theatre-ombres.pdf"},{"titre":"Radio Daillon","type":"interview","pdf":"/assets/pdf/ange/ange-7-9-10-interview.pdf"},{"titre":"Le baromètre du courage","type":"baromètre","pdf":"/assets/pdf/ange/ange-7-9-11-barometre.pdf"},{"titre":"Le permis de hurler","type":"diplôme","pdf":"/assets/pdf/ange/ange-7-9-12-diplome.pdf"}],"bonus":[{"titre":"Cherche les 12 différences","type":"jeu des différences","pdf":"/assets/pdf/ange/ange-7-9-bonus-1-jeu-des-differences.pdf"},{"titre":"L’histoire dans l’ordre","type":"vignettes","pdf":"/assets/pdf/ange/ange-7-9-bonus-2-vignettes.pdf"},{"titre":"Le cri de la forêt","type":"respiration","pdf":"/assets/pdf/ange/ange-7-9-bonus-3-cri-de-la-foret.pdf"}]},"video":"https://www.youtube-nocookie.com/embed/n7nQT0v49cU"}'::jsonb
) on conflict (slug) do update set contenu = excluded.contenu, titre = excluded.titre, theme = excluded.theme;
